(6886539, 1037620, 59737, '<td valign="top">funny title goes well with what you''re wearing, like how the textures of the window hide the details, and like the shadow your casting on the window.</td>', 'funny title goes well with what you''re wearing, like how the textures of the window hide the details, and like the shadow your casting on the window.', '2012-10-19 21:28:36.000000', NULL, 1),
(6886541, 1037650, 59737, '<td valign="top">Intense face, intense look and eyes, makes me think of a big brother, George Orwell type persona.  Lots of artifacts and noise on this.</td>', 'Intense face, intense look and eyes, makes me think of a big brother, George Orwell type persona.  Lots of artifacts and noise on this.', '2012-10-19 21:30:55.000000', NULL, 1),
